17	package com.google.zxing.common;
18	
19	import java.nio.charset.Charset;
20	import java.nio.charset.CharsetEncoder;
21	import java.nio.charset.StandardCharsets;
22	import java.nio.charset.UnsupportedCharsetException;
23	import java.util.ArrayList;
24	import java.util.List;
25	
26	/**
27	 * Set of CharsetEncoders for a given input string
28	 *
29	 * Invariants:
30	 * - The list contains only encoders from CharacterSetECI (list is shorter then the list of encoders available on
31	 *   the platform for which ECI values are defined).
32	 * - The list contains encoders at least one encoder for every character in the input.
33	 * - The first encoder in the list is always the ISO-8859-1 encoder even of no character in the input can be encoded
34	 *       by it.
35	 * - If the input contains a character that is not in ISO-8859-1 then the last two entries in the list will be the
36	 *   UTF-8 encoder and the UTF-16BE encoder.
37	 *
38	 * @author Alex Geller
39	 */
40	public final class ECIEncoderSet {
41	
42	  // List of encoders that potentially encode characters not in ISO-8859-1 in one byte.
43	  private static final List<CharsetEncoder> ENCODERS = new ArrayList<>();
44	  static {
45	    String[] names = { "IBM437",
46	                       "ISO-8859-2",
47	                       "ISO-8859-3",
48	                       "ISO-8859-4",
49	                       "ISO-8859-5",
50	                       "ISO-8859-6",
51	                       "ISO-8859-7",
52	                       "ISO-8859-8",
53	                       "ISO-8859-9",
54	                       "ISO-8859-10",
55	                       "ISO-8859-11",
56	                       "ISO-8859-13",
57	                       "ISO-8859-14",
58	                       "ISO-8859-15",
59	                       "ISO-8859-16",
60	                       "windows-1250",
61	                       "windows-1251",
62	                       "windows-1252",
63	                       "windows-1256",
64	                       "Shift_JIS" };
65	    for (String name : names) {
66	      if (CharacterSetECI.getCharacterSetECIByName(name) != null) {
67	        try {
68	          ENCODERS.add(Charset.forName(name).newEncoder());
69	        } catch (UnsupportedCharsetException e) {
70	          // continue
71	        }
72	      }
73	    }
74	  }
75	
76	  private final CharsetEncoder[] encoders;
77	  private final int priorityEncoderIndex;
78	
79	  /**
80	   * Constructs an encoder set
81	   *
82	   * @param stringToEncode the string that needs to be encoded
83	   * @param priorityCharset The preferred {@link Charset} or null.
84	   * @param fnc1 fnc1 denotes the character in the input that represents the FNC1 character or -1 for a non-GS1 bar
85	   * code. When specified, it is considered an error to pass it as argument to the methods canEncode() or encode().
86	   */
87	  public ECIEncoderSet(String stringToEncode, Charset priorityCharset, int fnc1) {
88	    List<CharsetEncoder> neededEncoders = new ArrayList<>();
89	
90	    //we always need the ISO-8859-1 encoder. It is the default encoding
91	    neededEncoders.add(StandardCharsets.ISO_8859_1.newEncoder());
92	    boolean needUnicodeEncoder = priorityCharset != null && priorityCharset.name().startsWith("UTF");
93	
94	    //Walk over the input string and see if all characters can be encoded with the list of encoders 
95	    for (int i = 0; i < stringToEncode.length(); i++) {
96	      boolean canEncode = false;
97	      for (CharsetEncoder encoder : neededEncoders) {
98	        char c = stringToEncode.charAt(i);
99	        if (c == fnc1 || encoder.canEncode(c)) {
100	          canEncode = true;
101	          break;
102	        }
103	      }
104	
105	      if (!canEncode) {
106	        //for the character at position i we don't yet have an encoder in the list
107	        for (CharsetEncoder encoder : ENCODERS) {
108	          if (encoder.canEncode(stringToEncode.charAt(i))) {
109	            //Good, we found an encoder that can encode the character. We add him to the list and continue scanning
110	            //the input
111	            neededEncoders.add(encoder);
112	            canEncode = true;
113	            break;
114	          }
115	        }
116	      }
117	
118	      if (!canEncode) {
119	        //The character is not encodeable by any of the single byte encoders so we remember that we will need a
120	        //Unicode encoder.
121	        needUnicodeEncoder = true;
122	      }
123	    }
124	  
125	    if (neededEncoders.size() == 1 && !needUnicodeEncoder) {
126	      //the entire input can be encoded by the ISO-8859-1 encoder
127	      encoders = new CharsetEncoder[] { neededEncoders.get(0) };
128	    } else {
129	      // we need more than one single byte encoder or we need a Unicode encoder.
130	      // In this case we append a UTF-8 and UTF-16 encoder to the list
131	      encoders = new CharsetEncoder[neededEncoders.size() + 2];
132	      int index = 0;
133	      for (CharsetEncoder encoder : neededEncoders) {
134	        encoders[index++] = encoder;
135	      }
136	
137	      encoders[index] = StandardCharsets.UTF_8.newEncoder();
138	      encoders[index + 1] = StandardCharsets.UTF_16BE.newEncoder();
139	    }
140	  
141	    //Compute priorityEncoderIndex by looking up priorityCharset in encoders
142	    int priorityEncoderIndexValue = -1;
143	    if (priorityCharset != null) {
144	      for (int i = 0; i < encoders.length; i++) {
145	        if (encoders[i] != null && priorityCharset.name().equals(encoders[i].charset().name())) {
146	          priorityEncoderIndexValue = i;
147	          break;
148	        }
149	      }
150	    }
151	    priorityEncoderIndex = priorityEncoderIndexValue;
152	    //invariants
153	    assert encoders[0].charset().equals(StandardCharsets.ISO_8859_1);
154	  }
155	
156	  public int length() {
157	    return encoders.length;
158	  }
159	
160	  public String getCharsetName(int index) {
161	    assert index < length();
162	    return encoders[index].charset().name();
163	  }
164	
165	  public Charset getCharset(int index) {
166	    assert index < length();
167	    return encoders[index].charset();
168	  }
169	
170	  public int getECIValue(int encoderIndex) {
171	    return CharacterSetECI.getCharacterSetECI(encoders[encoderIndex].charset()).getValue();
172	  }
173	
174	  /*
175	   *  returns -1 if no priority charset was defined
176	   */
177	  public int getPriorityEncoderIndex() {
178	    return priorityEncoderIndex;
179	  }
180	
181	  public boolean canEncode(char c, int encoderIndex) {
182	    assert encoderIndex < length();
183	    CharsetEncoder encoder = encoders[encoderIndex];
184	    return encoder.canEncode("" + c);
185	  }
186	
187	  public byte[] encode(char c, int encoderIndex) {
188	    assert encoderIndex < length();
189	    CharsetEncoder encoder = encoders[encoderIndex];
190	    assert encoder.canEncode("" + c);
191	    return ("" + c).getBytes(encoder.charset());
192	  }
193	
194	  public byte[] encode(String s, int encoderIndex) {
195	    assert encoderIndex < length();
196	    CharsetEncoder encoder = encoders[encoderIndex];
197	    return s.getBytes(encoder.charset());
198	  }
199	}
