17	package com.google.zxing.pdf417.decoder;
18	
19	import com.google.zxing.ResultPoint;
20	import com.google.zxing.pdf417.PDF417Common;
21	
22	/**
23	 * @author Guenther Grau
24	 */
25	final class DetectionResultRowIndicatorColumn extends DetectionResultColumn {
26	
27	  private final boolean isLeft;
28	
29	  DetectionResultRowIndicatorColumn(BoundingBox boundingBox, boolean isLeft) {
30	    super(boundingBox);
31	    this.isLeft = isLeft;
32	  }
33	
34	  private void setRowNumbers() {
35	    for (Codeword codeword : getCodewords()) {
36	      if (codeword != null) {
37	        codeword.setRowNumberAsRowIndicatorColumn();
38	      }
39	    }
40	  }
41	
42	  // TODO implement properly
43	  // TODO maybe we should add missing codewords to store the correct row number to make
44	  // finding row numbers for other columns easier
45	  // use row height count to make detection of invalid row numbers more reliable
46	  void adjustCompleteIndicatorColumnRowNumbers(BarcodeMetadata barcodeMetadata) {
47	    Codeword[] codewords = getCodewords();
48	    setRowNumbers();
49	    removeIncorrectCodewords(codewords, barcodeMetadata);
50	    BoundingBox boundingBox = getBoundingBox();
51	    ResultPoint top = isLeft ? boundingBox.getTopLeft() : boundingBox.getTopRight();
52	    ResultPoint bottom = isLeft ? boundingBox.getBottomLeft() : boundingBox.getBottomRight();
53	    int firstRow = imageRowToCodewordIndex((int) top.getY());
54	    int lastRow = imageRowToCodewordIndex((int) bottom.getY());
55	    // We need to be careful using the average row height. Barcode could be skewed so that we have smaller and
56	    // taller rows
57	    //float averageRowHeight = (lastRow - firstRow) / (float) barcodeMetadata.getRowCount();
58	    int barcodeRow = -1;
59	    int maxRowHeight = 1;
60	    int currentRowHeight = 0;
61	    for (int codewordsRow = firstRow; codewordsRow < lastRow; codewordsRow++) {
62	      if (codewords[codewordsRow] == null) {
63	        continue;
64	      }
65	      Codeword codeword = codewords[codewordsRow];
66	
67	      int rowDifference = codeword.getRowNumber() - barcodeRow;
68	
69	      // TODO improve handling with case where first row indicator doesn't start with 0
70	
71	      if (rowDifference == 0) {
72	        currentRowHeight++;
73	      } else if (rowDifference == 1) {
74	        maxRowHeight = Math.max(maxRowHeight, currentRowHeight);
75	        currentRowHeight = 1;
76	        barcodeRow = codeword.getRowNumber();
77	      } else if (rowDifference < 0 ||
78	                 codeword.getRowNumber() >= barcodeMetadata.getRowCount() ||
79	                 rowDifference > codewordsRow) {
80	        codewords[codewordsRow] = null;
81	      } else {
82	        int checkedRows;
83	        if (maxRowHeight > 2) {
84	          checkedRows = (maxRowHeight - 2) * rowDifference;
85	        } else {
86	          checkedRows = rowDifference;
87	        }
88	        boolean closePreviousCodewordFound = checkedRows >= codewordsRow;
89	        for (int i = 1; i <= checkedRows && !closePreviousCodewordFound; i++) {
90	          // there must be (height * rowDifference) number of codewords missing. For now we assume height = 1.
91	          // This should hopefully get rid of most problems already.
92	          closePreviousCodewordFound = codewords[codewordsRow - i] != null;
93	        }
94	        if (closePreviousCodewordFound) {
95	          codewords[codewordsRow] = null;
96	        } else {
97	          barcodeRow = codeword.getRowNumber();
98	          currentRowHeight = 1;
99	        }
100	      }
101	    }
102	    //return (int) (averageRowHeight + 0.5);
103	  }
104	
105	  int[] getRowHeights() {
106	    BarcodeMetadata barcodeMetadata = getBarcodeMetadata();
107	    if (barcodeMetadata == null) {
108	      return null;
109	    }
110	    adjustIncompleteIndicatorColumnRowNumbers(barcodeMetadata);
111	    int[] result = new int[barcodeMetadata.getRowCount()];
112	    for (Codeword codeword : getCodewords()) {
113	      if (codeword != null) {
114	        int rowNumber = codeword.getRowNumber();
115	        if (rowNumber >= result.length) {
116	          // We have more rows than the barcode metadata allows for, ignore them.
117	          continue;
118	        }
119	        result[rowNumber]++;
120	      } // else throw exception?
121	    }
122	    return result;
123	  }
124	
125	  // TODO maybe we should add missing codewords to store the correct row number to make
126	  // finding row numbers for other columns easier
127	  // use row height count to make detection of invalid row numbers more reliable
128	  private void adjustIncompleteIndicatorColumnRowNumbers(BarcodeMetadata barcodeMetadata) {
129	    BoundingBox boundingBox = getBoundingBox();
130	    ResultPoint top = isLeft ? boundingBox.getTopLeft() : boundingBox.getTopRight();
131	    ResultPoint bottom = isLeft ? boundingBox.getBottomLeft() : boundingBox.getBottomRight();
132	    int firstRow = imageRowToCodewordIndex((int) top.getY());
133	    int lastRow = imageRowToCodewordIndex((int) bottom.getY());
134	    //float averageRowHeight = (lastRow - firstRow) / (float) barcodeMetadata.getRowCount();
135	    Codeword[] codewords = getCodewords();
136	    int barcodeRow = -1;
137	    int maxRowHeight = 1;
138	    int currentRowHeight = 0;
139	    for (int codewordsRow = firstRow; codewordsRow < lastRow; codewordsRow++) {
140	      if (codewords[codewordsRow] == null) {
141	        continue;
142	      }
143	      Codeword codeword = codewords[codewordsRow];
144	
145	      codeword.setRowNumberAsRowIndicatorColumn();
146	
147	      int rowDifference = codeword.getRowNumber() - barcodeRow;
148	
149	      // TODO improve handling with case where first row indicator doesn't start with 0
150	
151	      if (rowDifference == 0) {
152	        currentRowHeight++;
153	      } else if (rowDifference == 1) {
154	        maxRowHeight = Math.max(maxRowHeight, currentRowHeight);
155	        currentRowHeight = 1;
156	        barcodeRow = codeword.getRowNumber();
157	      } else if (codeword.getRowNumber() >= barcodeMetadata.getRowCount()) {
158	        codewords[codewordsRow] = null;
159	      } else {
160	        barcodeRow = codeword.getRowNumber();
161	        currentRowHeight = 1;
162	      }
163	    }
164	    //return (int) (averageRowHeight + 0.5);
165	  }
166	
167	  BarcodeMetadata getBarcodeMetadata() {
168	    Codeword[] codewords = getCodewords();
169	    BarcodeValue barcodeColumnCount = new BarcodeValue();
170	    BarcodeValue barcodeRowCountUpperPart = new BarcodeValue();
171	    BarcodeValue barcodeRowCountLowerPart = new BarcodeValue();
172	    BarcodeValue barcodeECLevel = new BarcodeValue();
173	    for (Codeword codeword : codewords) {
174	      if (codeword == null) {
175	        continue;
176	      }
177	      codeword.setRowNumberAsRowIndicatorColumn();
178	      int rowIndicatorValue = codeword.getValue() % 30;
179	      int codewordRowNumber = codeword.getRowNumber();
180	      if (!isLeft) {
181	        codewordRowNumber += 2;
182	      }
183	      switch (codewordRowNumber % 3) {
184	        case 0:
185	          barcodeRowCountUpperPart.setValue(rowIndicatorValue * 3 + 1);
186	          break;
187	        case 1:
188	          barcodeECLevel.setValue(rowIndicatorValue / 3);
189	          barcodeRowCountLowerPart.setValue(rowIndicatorValue % 3);
190	          break;
191	        case 2:
192	          barcodeColumnCount.setValue(rowIndicatorValue + 1);
193	          break;
194	      }
195	    }
196	    // Maybe we should check if we have ambiguous values?
197	    if ((barcodeColumnCount.getValue().length == 0) ||
198	        (barcodeRowCountUpperPart.getValue().length == 0) ||
199	        (barcodeRowCountLowerPart.getValue().length == 0) ||
200	        (barcodeECLevel.getValue().length == 0) ||
201	        barcodeColumnCount.getValue()[0] < 1 ||
202	        barcodeRowCountUpperPart.getValue()[0] + barcodeRowCountLowerPart.getValue()[0] <
203	            PDF417Common.MIN_ROWS_IN_BARCODE ||
204	        barcodeRowCountUpperPart.getValue()[0] + barcodeRowCountLowerPart.getValue()[0] >
205	            PDF417Common.MAX_ROWS_IN_BARCODE) {
206	      return null;
207	    }
208	    BarcodeMetadata barcodeMetadata = new BarcodeMetadata(barcodeColumnCount.getValue()[0],
209	        barcodeRowCountUpperPart.getValue()[0], barcodeRowCountLowerPart.getValue()[0], barcodeECLevel.getValue()[0]);
210	    removeIncorrectCodewords(codewords, barcodeMetadata);
211	    return barcodeMetadata;
212	  }
213	
214	  private void removeIncorrectCodewords(Codeword[] codewords, BarcodeMetadata barcodeMetadata) {
215	    // Remove codewords which do not match the metadata
216	    // TODO Maybe we should keep the incorrect codewords for the start and end positions?
217	    for (int codewordRow = 0; codewordRow < codewords.length; codewordRow++) {
218	      Codeword codeword = codewords[codewordRow];
219	      if (codewords[codewordRow] == null) {
220	        continue;
221	      }
222	      int rowIndicatorValue = codeword.getValue() % 30;
223	      int codewordRowNumber = codeword.getRowNumber();
224	      if (codewordRowNumber > barcodeMetadata.getRowCount()) {
225	        codewords[codewordRow] = null;
226	        continue;
227	      }
228	      if (!isLeft) {
229	        codewordRowNumber += 2;
230	      }
231	      switch (codewordRowNumber % 3) {
232	        case 0:
233	          if (rowIndicatorValue * 3 + 1 != barcodeMetadata.getRowCountUpperPart()) {
234	            codewords[codewordRow] = null;
235	          }
236	          break;
237	        case 1:
238	          if (rowIndicatorValue / 3 != barcodeMetadata.getErrorCorrectionLevel() ||
239	              rowIndicatorValue % 3 != barcodeMetadata.getRowCountLowerPart()) {
240	            codewords[codewordRow] = null;
241	          }
242	          break;
243	        case 2:
244	          if (rowIndicatorValue + 1 != barcodeMetadata.getColumnCount()) {
245	            codewords[codewordRow] = null;
246	          }
247	          break;
248	      }
249	    }
250	  }
251	
252	  boolean isLeft() {
253	    return isLeft;
254	  }
255	
256	  @Override
257	  public String toString() {
258	    return "IsLeft: " + isLeft + '\n' + super.toString();
259	  }
260	
261	}
