24	/**
25	 * Class that converts a sequence of ECIs and bytes into a string
26	 *
27	 * @author Alex Geller
28	 */
29	public final class ECIStringBuilder {
30	  private StringBuilder currentBytes;
31	  private StringBuilder result;
32	  private Charset currentCharset = StandardCharsets.ISO_8859_1;
33	
34	  public ECIStringBuilder() {
35	    currentBytes = new StringBuilder();
36	  }
37	  public ECIStringBuilder(int initialCapacity) {
38	    currentBytes = new StringBuilder(initialCapacity);
39	  }
40	
41	  /**
42	   * Appends {@code value} as a byte value
43	   *
44	   * @param value character whose lowest byte is to be appended
45	   */
46	  public void append(char value) {
47	    currentBytes.append((char) (value & 0xff));
48	  }
49	
50	  /**
51	   * Appends {@code value} as a byte value
52	   *
53	   * @param value byte to append
54	   */
55	  public void append(byte value) {
56	    currentBytes.append((char) (value & 0xff));
57	  }
58	
59	  /**
60	   * Appends the characters in {@code value} as bytes values
61	   *
62	   * @param value string to append
63	   */
64	  public void append(String value) {
65	    currentBytes.append(value);
66	  }
67	
68	  /**
69	   * Append the string repesentation of {@code value} (short for {@code append(String.valueOf(value))})
70	   *
71	   * @param value int to append as a string
72	   */
73	  public void append(int value) {
74	    append(String.valueOf(value));
75	  }
76	
77	  /**
78	   * Appends ECI value to output.
79	   *
80	   * @param value ECI value to append, as an int
81	   * @throws FormatException on invalid ECI value
82	   */
83	  public void appendECI(int value) throws FormatException {
84	    encodeCurrentBytesIfAny();
85	    CharacterSetECI characterSetECI = CharacterSetECI.getCharacterSetECIByValue(value);
86	    if (characterSetECI == null) {
87	      throw FormatException.getFormatInstance();
88	    }
89	    currentCharset = characterSetECI.getCharset();
90	  }
91	
92	  private void encodeCurrentBytesIfAny() {
93	    if (currentCharset.equals(StandardCharsets.ISO_8859_1)) {
94	      if (currentBytes.length() > 0) {
95	        if (result == null) {
96	          result = currentBytes;
97	          currentBytes = new StringBuilder();
98	        } else {
99	          result.append(currentBytes);
100	          currentBytes = new StringBuilder();
101	        }
102	      }
103	    } else if (currentBytes.length() > 0) {
104	      byte[] bytes = currentBytes.toString().getBytes(StandardCharsets.ISO_8859_1);
105	      currentBytes = new StringBuilder();
106	      if (result == null) {
107	        result = new StringBuilder(new String(bytes, currentCharset));
108	      } else {
109	        result.append(new String(bytes, currentCharset));
110	      }
111	    }
112	  }
113	
114	  /**
115	   * Appends the characters from {@code value} (unlike all other append methods of this class who append bytes)
116	   *
117	   * @param value characters to append
118	   */
119	  public void appendCharacters(StringBuilder value) {
120	    encodeCurrentBytesIfAny();
121	    result.append(value);
122	  }
123	
124	  /**
125	   * Short for {@code toString().length()} (if possible, use {@link #isEmpty()} instead)
126	   *
127	   * @return length of string representation in characters
128	   */
129	  public int length() {
130	    return toString().length();
131	  }
132	
133	  /**
134	   * @return true iff nothing has been appended
135	   */
136	  public boolean isEmpty() {
137	    return currentBytes.length() == 0 && (result == null || result.length() == 0);
138	  }
139	
140	  @Override
141	  public String toString() {
142	    encodeCurrentBytesIfAny();
143	    return result == null ? "" : result.toString();
144	  }
145	}
