17	package com.google.zxing.qrcode.decoder;
18	
19	/**
20	 * <p>Encapsulates a QR Code's format information, including the data mask used and
21	 * error correction level.</p>
22	 *
23	 * @author Sean Owen
24	 * @see DataMask
25	 * @see ErrorCorrectionLevel
26	 */
27	final class FormatInformation {
28	
29	  private static final int FORMAT_INFO_MASK_QR = 0x5412;
30	
31	  /**
32	   * See ISO 18004:2006, Annex C, Table C.1
33	   */
34	  private static final int[][] FORMAT_INFO_DECODE_LOOKUP = {
35	      {0x5412, 0x00},
36	      {0x5125, 0x01},
37	      {0x5E7C, 0x02},
38	      {0x5B4B, 0x03},
39	      {0x45F9, 0x04},
40	      {0x40CE, 0x05},
41	      {0x4F97, 0x06},
42	      {0x4AA0, 0x07},
43	      {0x77C4, 0x08},
44	      {0x72F3, 0x09},
45	      {0x7DAA, 0x0A},
46	      {0x789D, 0x0B},
47	      {0x662F, 0x0C},
48	      {0x6318, 0x0D},
49	      {0x6C41, 0x0E},
50	      {0x6976, 0x0F},
51	      {0x1689, 0x10},
52	      {0x13BE, 0x11},
53	      {0x1CE7, 0x12},
54	      {0x19D0, 0x13},
55	      {0x0762, 0x14},
56	      {0x0255, 0x15},
57	      {0x0D0C, 0x16},
58	      {0x083B, 0x17},
59	      {0x355F, 0x18},
60	      {0x3068, 0x19},
61	      {0x3F31, 0x1A},
62	      {0x3A06, 0x1B},
63	      {0x24B4, 0x1C},
64	      {0x2183, 0x1D},
65	      {0x2EDA, 0x1E},
66	      {0x2BED, 0x1F},
67	  };
68	
69	  private final ErrorCorrectionLevel errorCorrectionLevel;
70	  private final byte dataMask;
71	
72	  private FormatInformation(int formatInfo) {
73	    // Bits 3,4
74	    errorCorrectionLevel = ErrorCorrectionLevel.forBits((formatInfo >> 3) & 0x03);
75	    // Bottom 3 bits
76	    dataMask = (byte) (formatInfo & 0x07);
77	  }
78	
79	  static int numBitsDiffering(int a, int b) {
80	    return Integer.bitCount(a ^ b);
81	  }
82	
83	  /**
84	   * @param maskedFormatInfo1 format info indicator, with mask still applied
85	   * @param maskedFormatInfo2 second copy of same info; both are checked at the same time
86	   *  to establish best match
87	   * @return information about the format it specifies, or {@code null}
88	   *  if doesn't seem to match any known pattern
89	   */
90	  static FormatInformation decodeFormatInformation(int maskedFormatInfo1, int maskedFormatInfo2) {
91	    FormatInformation formatInfo = doDecodeFormatInformation(maskedFormatInfo1, maskedFormatInfo2);
92	    if (formatInfo != null) {
93	      return formatInfo;
94	    }
95	    // Should return null, but, some QR codes apparently
96	    // do not mask this info. Try again by actually masking the pattern
97	    // first
98	    return doDecodeFormatInformation(maskedFormatInfo1 ^ FORMAT_INFO_MASK_QR,
99	                                     maskedFormatInfo2 ^ FORMAT_INFO_MASK_QR);
100	  }
101	
102	  private static FormatInformation doDecodeFormatInformation(int maskedFormatInfo1, int maskedFormatInfo2) {
103	    // Find the int in FORMAT_INFO_DECODE_LOOKUP with fewest bits differing
104	    int bestDifference = Integer.MAX_VALUE;
105	    int bestFormatInfo = 0;
106	    for (int[] decodeInfo : FORMAT_INFO_DECODE_LOOKUP) {
107	      int targetInfo = decodeInfo[0];
108	      if (targetInfo == maskedFormatInfo1 || targetInfo == maskedFormatInfo2) {
109	        // Found an exact match
110	        return new FormatInformation(decodeInfo[1]);
111	      }
112	      int bitsDifference = numBitsDiffering(maskedFormatInfo1, targetInfo);
113	      if (bitsDifference < bestDifference) {
114	        bestFormatInfo = decodeInfo[1];
115	        bestDifference = bitsDifference;
116	      }
117	      if (maskedFormatInfo1 != maskedFormatInfo2) {
118	        // also try the other option
119	        bitsDifference = numBitsDiffering(maskedFormatInfo2, targetInfo);
120	        if (bitsDifference < bestDifference) {
121	          bestFormatInfo = decodeInfo[1];
122	          bestDifference = bitsDifference;
123	        }
124	      }
125	    }
126	    // Hamming distance of the 32 masked codes is 7, by construction, so <= 3 bits
127	    // differing means we found a match
128	    if (bestDifference <= 3) {
129	      return new FormatInformation(bestFormatInfo);
130	    }
131	    return null;
132	  }
133	
134	  ErrorCorrectionLevel getErrorCorrectionLevel() {
135	    return errorCorrectionLevel;
136	  }
137	
138	  byte getDataMask() {
139	    return dataMask;
140	  }
141	
142	  @Override
143	  public int hashCode() {
144	    return (errorCorrectionLevel.ordinal() << 3) | dataMask;
145	  }
146	
147	  @Override
148	  public boolean equals(Object o) {
149	    if (!(o instanceof FormatInformation)) {
150	      return false;
151	    }
152	    FormatInformation other = (FormatInformation) o;
153	    return this.errorCorrectionLevel == other.errorCorrectionLevel &&
154	        this.dataMask == other.dataMask;
155	  }
156	
157	}
