17	package com.google.zxing.pdf417.decoder;
18	
19	import com.google.zxing.NotFoundException;
20	import com.google.zxing.ResultPoint;
21	import com.google.zxing.common.BitMatrix;
22	
23	/**
24	 * @author Guenther Grau
25	 */
26	final class BoundingBox {
27	
28	  private final BitMatrix image;
29	  private final ResultPoint topLeft;
30	  private final ResultPoint bottomLeft;
31	  private final ResultPoint topRight;
32	  private final ResultPoint bottomRight;
33	  private final int minX;
34	  private final int maxX;
35	  private final int minY;
36	  private final int maxY;
37	
38	  BoundingBox(BitMatrix image,
39	              ResultPoint topLeft,
40	              ResultPoint bottomLeft,
41	              ResultPoint topRight,
42	              ResultPoint bottomRight) throws NotFoundException {
43	    boolean leftUnspecified = topLeft == null || bottomLeft == null;
44	    boolean rightUnspecified = topRight == null || bottomRight == null;
45	    if (leftUnspecified && rightUnspecified) {
46	      throw NotFoundException.getNotFoundInstance();
47	    }
48	    if (leftUnspecified) {
49	      topLeft = new ResultPoint(0, topRight.getY());
50	      bottomLeft = new ResultPoint(0, bottomRight.getY());
51	    } else if (rightUnspecified) {
52	      topRight = new ResultPoint(image.getWidth() - 1, topLeft.getY());
53	      bottomRight = new ResultPoint(image.getWidth() - 1, bottomLeft.getY());
54	    }
55	    this.image = image;
56	    this.topLeft = topLeft;
57	    this.bottomLeft = bottomLeft;
58	    this.topRight = topRight;
59	    this.bottomRight = bottomRight;
60	    this.minX = (int) Math.min(topLeft.getX(), bottomLeft.getX());
61	    this.maxX = (int) Math.max(topRight.getX(), bottomRight.getX());
62	    this.minY = (int) Math.min(topLeft.getY(), topRight.getY());
63	    this.maxY = (int) Math.max(bottomLeft.getY(), bottomRight.getY());
64	  }
65	
66	  BoundingBox(BoundingBox boundingBox) {
67	    this.image = boundingBox.image;
68	    this.topLeft = boundingBox.topLeft;
69	    this.bottomLeft = boundingBox.bottomLeft;
70	    this.topRight = boundingBox.topRight;
71	    this.bottomRight = boundingBox.bottomRight;
72	    this.minX = boundingBox.minX;
73	    this.maxX = boundingBox.maxX;
74	    this.minY = boundingBox.minY;
75	    this.maxY = boundingBox.maxY;
76	  }
77	
78	  static BoundingBox merge(BoundingBox leftBox, BoundingBox rightBox) throws NotFoundException {
79	    if (leftBox == null) {
80	      return rightBox;
81	    }
82	    if (rightBox == null) {
83	      return leftBox;
84	    }
85	    return new BoundingBox(leftBox.image, leftBox.topLeft, leftBox.bottomLeft, rightBox.topRight, rightBox.bottomRight);
86	  }
87	
88	  BoundingBox addMissingRows(int missingStartRows, int missingEndRows, boolean isLeft) throws NotFoundException {
89	    ResultPoint newTopLeft = topLeft;
90	    ResultPoint newBottomLeft = bottomLeft;
91	    ResultPoint newTopRight = topRight;
92	    ResultPoint newBottomRight = bottomRight;
93	
94	    if (missingStartRows > 0) {
95	      ResultPoint top = isLeft ? topLeft : topRight;
96	      int newMinY = (int) top.getY() - missingStartRows;
97	      if (newMinY < 0) {
98	        newMinY = 0;
99	      }
100	      ResultPoint newTop = new ResultPoint(top.getX(), newMinY);
101	      if (isLeft) {
102	        newTopLeft = newTop;
103	      } else {
104	        newTopRight = newTop;
105	      }
106	    }
107	
108	    if (missingEndRows > 0) {
109	      ResultPoint bottom = isLeft ? bottomLeft : bottomRight;
110	      int newMaxY = (int) bottom.getY() + missingEndRows;
111	      if (newMaxY >= image.getHeight()) {
112	        newMaxY = image.getHeight() - 1;
113	      }
114	      ResultPoint newBottom = new ResultPoint(bottom.getX(), newMaxY);
115	      if (isLeft) {
116	        newBottomLeft = newBottom;
117	      } else {
118	        newBottomRight = newBottom;
119	      }
120	    }
121	
122	    return new BoundingBox(image, newTopLeft, newBottomLeft, newTopRight, newBottomRight);
123	  }
124	
125	  int getMinX() {
126	    return minX;
127	  }
128	
129	  int getMaxX() {
130	    return maxX;
131	  }
132	
133	  int getMinY() {
134	    return minY;
135	  }
136	
137	  int getMaxY() {
138	    return maxY;
139	  }
140	
141	  ResultPoint getTopLeft() {
142	    return topLeft;
143	  }
144	
145	  ResultPoint getTopRight() {
146	    return topRight;
147	  }
148	
149	  ResultPoint getBottomLeft() {
150	    return bottomLeft;
151	  }
152	
153	  ResultPoint getBottomRight() {
154	    return bottomRight;
155	  }
156	
157	}
