17	package com.google.zxing.datamatrix.encoder;
18	
19	class C40Encoder implements Encoder {
20	
21	  @Override
22	  public int getEncodingMode() {
23	    return HighLevelEncoder.C40_ENCODATION;
24	  }
25	
26	  void encodeMaximal(EncoderContext context) {
27	    StringBuilder buffer = new StringBuilder();
28	    int lastCharSize = 0;
29	    int backtrackStartPosition = context.pos;
30	    int backtrackBufferLength = 0;
31	    while (context.hasMoreCharacters()) {
32	      char c = context.getCurrentChar();
33	      context.pos++;
34	      lastCharSize = encodeChar(c, buffer);
35	      if (buffer.length() % 3 == 0) {
36	        backtrackStartPosition = context.pos;
37	        backtrackBufferLength = buffer.length();
38	      }
39	    }
40	    if (backtrackBufferLength != buffer.length()) {
41	      int unwritten = (buffer.length() / 3) * 2;
42	
43	      int curCodewordCount = context.getCodewordCount() + unwritten + 1; // +1 for the latch to C40
44	      context.updateSymbolInfo(curCodewordCount);
45	      int available = context.getSymbolInfo().getDataCapacity() - curCodewordCount;
46	      int rest = buffer.length() % 3;
47	      if ((rest == 2 && available != 2) ||
48	          (rest == 1 && (lastCharSize > 3 || available != 1))) {
49	        buffer.setLength(backtrackBufferLength);
50	        context.pos = backtrackStartPosition;
51	      }
52	    }
53	    if (buffer.length() > 0) {
54	      context.writeCodeword(HighLevelEncoder.LATCH_TO_C40);
55	    }
56	  
57	    handleEOD(context, buffer);
58	  }
59	
60	  @Override
61	  public void encode(EncoderContext context) {
62	    //step C
63	    StringBuilder buffer = new StringBuilder();
64	    while (context.hasMoreCharacters()) {
65	      char c = context.getCurrentChar();
66	      context.pos++;
67	
68	      int lastCharSize = encodeChar(c, buffer);
69	
70	      int unwritten = (buffer.length() / 3) * 2;
71	
72	      int curCodewordCount = context.getCodewordCount() + unwritten;
73	      context.updateSymbolInfo(curCodewordCount);
74	      int available = context.getSymbolInfo().getDataCapacity() - curCodewordCount;
75	
76	      if (!context.hasMoreCharacters()) {
77	        //Avoid having a single C40 value in the last triplet
78	        StringBuilder removed = new StringBuilder();
79	        if ((buffer.length() % 3) == 2 && available != 2) {
80	          lastCharSize = backtrackOneCharacter(context, buffer, removed, lastCharSize);
81	        }
82	        while ((buffer.length() % 3) == 1 && (lastCharSize > 3 || available != 1)) {
83	          lastCharSize = backtrackOneCharacter(context, buffer, removed, lastCharSize);
84	        }
85	        break;
86	      }
87	
88	      int count = buffer.length();
89	      if ((count % 3) == 0) {
90	        int newMode = HighLevelEncoder.lookAheadTest(context.getMessage(), context.pos, getEncodingMode());
91	        if (newMode != getEncodingMode()) {
92	          // Return to ASCII encodation, which will actually handle latch to new mode
93	          context.signalEncoderChange(HighLevelEncoder.ASCII_ENCODATION);
94	          break;
95	        }
96	      }
97	    }
98	    handleEOD(context, buffer);
99	  }
100	
101	  private int backtrackOneCharacter(EncoderContext context,
102	                                    StringBuilder buffer, StringBuilder removed, int lastCharSize) {
103	    int count = buffer.length();
104	    buffer.delete(count - lastCharSize, count);
105	    context.pos--;
106	    char c = context.getCurrentChar();
107	    lastCharSize = encodeChar(c, removed);
108	    context.resetSymbolInfo(); //Deal with possible reduction in symbol size
109	    return lastCharSize;
110	  }
111	
112	  static void writeNextTriplet(EncoderContext context, StringBuilder buffer) {
113	    context.writeCodewords(encodeToCodewords(buffer));
114	    buffer.delete(0, 3);
115	  }
116	
117	  /**
118	   * Handle "end of data" situations
119	   *
120	   * @param context the encoder context
121	   * @param buffer  the buffer with the remaining encoded characters
122	   */
123	  void handleEOD(EncoderContext context, StringBuilder buffer) {
124	    int unwritten = (buffer.length() / 3) * 2;
125	    int rest = buffer.length() % 3;
126	
127	    int curCodewordCount = context.getCodewordCount() + unwritten;
128	    context.updateSymbolInfo(curCodewordCount);
129	    int available = context.getSymbolInfo().getDataCapacity() - curCodewordCount;
130	
131	    if (rest == 2) {
132	      buffer.append('\0'); //Shift 1
133	      while (buffer.length() >= 3) {
134	        writeNextTriplet(context, buffer);
135	      }
136	      if (context.hasMoreCharacters()) {
137	        context.writeCodeword(HighLevelEncoder.C40_UNLATCH);
138	      }
139	    } else if (available == 1 && rest == 1) {
140	      while (buffer.length() >= 3) {
141	        writeNextTriplet(context, buffer);
142	      }
143	      if (context.hasMoreCharacters()) {
144	        context.writeCodeword(HighLevelEncoder.C40_UNLATCH);
145	      }
146	      // else no unlatch
147	      context.pos--;
148	    } else if (rest == 0) {
149	      while (buffer.length() >= 3) {
150	        writeNextTriplet(context, buffer);
151	      }
152	      if (available > 0 || context.hasMoreCharacters()) {
153	        context.writeCodeword(HighLevelEncoder.C40_UNLATCH);
154	      }
155	    } else {
156	      throw new IllegalStateException("Unexpected case. Please report!");
157	    }
158	    context.signalEncoderChange(HighLevelEncoder.ASCII_ENCODATION);
159	  }
160	
161	  int encodeChar(char c, StringBuilder sb) {
162	    if (c == ' ') {
163	      sb.append('\3');
164	      return 1;
165	    }
166	    if (c >= '0' && c <= '9') {
167	      sb.append((char) (c - 48 + 4));
168	      return 1;
169	    }
170	    if (c >= 'A' && c <= 'Z') {
171	      sb.append((char) (c - 65 + 14));
172	      return 1;
173	    }
174	    if (c < ' ') {
175	      sb.append('\0'); //Shift 1 Set
176	      sb.append(c);
177	      return 2;
178	    }
179	    if (c <= '/') {
180	      sb.append('\1'); //Shift 2 Set
181	      sb.append((char) (c - 33));
182	      return 2;
183	    }
184	    if (c <= '@') {
185	      sb.append('\1'); //Shift 2 Set
186	      sb.append((char) (c - 58 + 15));
187	      return 2;
188	    }
189	    if (c <= '_') {
190	      sb.append('\1'); //Shift 2 Set
191	      sb.append((char) (c - 91 + 22));
192	      return 2;
193	    }
194	    if (c <= 127) {
195	      sb.append('\2'); //Shift 3 Set
196	      sb.append((char) (c - 96));
197	      return 2;
198	    }
199	    sb.append("\1\u001e"); //Shift 2, Upper Shift
200	    int len = 2;
201	    len += encodeChar((char) (c - 128), sb);
202	    return len;
203	  }
204	
205	  private static String encodeToCodewords(CharSequence sb) {
206	    int v = (1600 * sb.charAt(0)) + (40 * sb.charAt(1)) + sb.charAt(2) + 1;
207	    char cw1 = (char) (v / 256);
208	    char cw2 = (char) (v % 256);
209	    return new String(new char[] {cw1, cw2});
210	  }
211	
212	}
