import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Arrays;
import java.util.Random;

/** Differential test for GridSampler.checkAndNudgePoints: original vs refactored (nudge extraction). */
public final class GsDiff {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  static final class Api {
    final java.lang.reflect.Constructor<?> bmCtor;
    final Method check;
    Api(ClassLoader cl) throws Exception {
      Class<?> bm = Class.forName("com.google.zxing.common.BitMatrix", true, cl);
      bmCtor = bm.getConstructor(int.class, int.class);
      Class<?> gs = Class.forName("com.google.zxing.common.GridSampler", true, cl);
      check = gs.getDeclaredMethod("checkAndNudgePoints", bm, float[].class);
      check.setAccessible(true);
    }
    // Returns "OK|<mutated array>" or "EX|<exceptionClass>". Operates on a copy of points.
    String run(int w, int h, float[] points) {
      try {
        Object image = bmCtor.newInstance(w, h);
        float[] copy = points.clone();
        check.invoke(null, image, copy);
        return "OK|" + Arrays.toString(copy);
      } catch (Throwable t) {
        Throwable c = (t.getCause() != null) ? t.getCause() : t;
        return "EX|" + c.getClass().getName();
      }
    }
  }

  public static void main(String[] args) throws Exception {
    Api oldA = new Api(loader(args[0]));
    Api newA = new Api(loader(args[1]));
    Random r = new Random(1234);

    long total = 0;
    long ok = 0;
    long nudgedSeen = 0;
    long mism = 0;

    int[] dims = { 1, 2, 5, 16, 33, 64 };
    for (int trial = 0; trial < 500000; trial++) {
      int w = dims[r.nextInt(dims.length)];
      int h = dims[r.nextInt(dims.length)];
      int pairs = 1 + r.nextInt(6);
      float[] points = new float[pairs * 2];
      for (int i = 0; i < points.length; i++) {
        boolean isX = (i % 2) == 0;
        int bound = isX ? w : h;
        // bias toward edge/boundary values to exercise nudging and throwing
        int pick = r.nextInt(10);
        float v;
        switch (pick) {
          case 0: v = -1f; break;
          case 1: v = 0f; break;
          case 2: v = bound; break;        // == width/height -> nudge
          case 3: v = bound + 1; break;    // -> throw
          case 4: v = -2f; break;          // -> throw
          case 5: v = -0.5f; break;        // (int) -> 0, not -1
          case 6: v = -1.5f; break;        // (int) -> -1 -> nudge
          case 7: v = bound + 0.5f; break; // (int) -> bound -> nudge (since (int) truncates)
          case 8: v = r.nextInt(bound + 3) - 1; break;
          default: v = (r.nextFloat() * (bound + 4)) - 2f; break;
        }
        points[i] = v;
      }
      String a = oldA.run(w, h, points);
      String b = newA.run(w, h, points);
      total++;
      if (a.startsWith("OK")) {
        ok++;
        // crude check that some nudging occurred (output differs from input)
        if (!a.equals("OK|" + Arrays.toString(points))) {
          nudgedSeen++;
        }
      }
      if (!a.equals(b)) {
        mism++;
        if (mism <= 20) {
          System.out.println("MISMATCH w=" + w + " h=" + h + " in=" + Arrays.toString(points));
          System.out.println("  old: " + a);
          System.out.println("  new: " + b);
        }
      }
    }
    System.out.println("----");
    System.out.println("Total calls:        " + total);
    System.out.println("Successful (OK):     " + ok + " (of which nudged: " + nudgedSeen + ")");
    System.out.println("Mismatches:         " + mism);
    System.out.println(mism == 0 ? "RESULT: IDENTICAL BEHAVIOR" : "RESULT: DIFFERENCES FOUND");
  }
}

