-        points[offset + 1] = height - 1;
-        nudged = true;
-      }
+      nudged = nudge(points, offset, width, height);
     }
     // Check and nudge points from end:
     nudged = true;
     for (int offset = points.length - 2; offset >= 0 && nudged; offset -= 2) {
-      int x = (int) points[offset];
-      int y = (int) points[offset + 1];
-      if (x < -1 || x > width || y < -1 || y > height) {
-        throw NotFoundException.getNotFoundInstance();
-      }
-      nudged = false;
-      if (x == -1) {
-        points[offset] = 0.0f;
-        nudged = true;
-      } else if (x == width) {
-        points[offset] = width - 1;
-        nudged = true;
-      }
-      if (y == -1) {
-        points[offset + 1] = 0.0f;
-        nudged = true;
-      } else if (y == height) {
-        points[offset + 1] = height - 1;
-        nudged = true;
-      }
+      nudged = nudge(points, offset, width, height);
     }
   }

+  /**
+   * Checks the point at {@code offset} (an x,y pair) against the image bounds, nudging it back onto
+   * the image if it is barely (less than 1 pixel) off an edge.
+   *
+   * @return {@code true} if the point was nudged
+   * @throws NotFoundException if the point lies more than one pixel outside the image boundaries
+   */
+  private static boolean nudge(float[] points, int offset, int width, int height) throws NotFoundException {
+    int x = (int) points[offset];
+    int y = (int) points[offset + 1];
+    if (x < -1 || x > width || y < -1 || y > height) {
+      throw NotFoundException.getNotFoundInstance();
+    }
+    boolean nudged = false;
+    if (x == -1) {
+      points[offset] = 0.0f;
+      nudged = true;
+    } else if (x == width) {
+      points[offset] = width - 1;
+      nudged = true;
+    }
+    if (y == -1) {
+      points[offset + 1] = 0.0f;
+      nudged = true;
+    } else if (y == height) {
+      points[offset + 1] = height - 1;
+      nudged = true;
+    }
+    return nudged;
+  }
+
 }

